function card(p,index){return `<li class="project-card reveal" data-scroll data-scroll-speed="${index%2 ? '.4':'0'}"><a href="/modulos/${e(p.slug)}/" class="project-card-content" data-cursor="Explorar"><div class="card-image composition-${index+1}" style="--card-accent:${e(p.accent || '#753947')}"><div class="card-art-number" aria-hidden="true">0${index+1}</div><img src="/${e(p.cover).replace(/^\//,'')}" alt="Interface do módulo ${e(p.title)} da Innecta" width="1400" height="1000" loading="lazy"><span class="card-art-label" aria-hidden="true">${e(p.title)}</span><span class="card-arrow">↗</span></div><div class="card-caption"><h3>${e(p.title)}</h3><span>${e(p.category)}</span></div></a></li>`;}
export function renderHome(){return `<div class="home-world" data-shared-scene><div class="shared-artwork" data-shared-artwork data-render-mode="pending" aria-hidden="true"><div class="hero-fallback" aria-hidden="true"><div class="fallback-field"></div><div class="fallback-lens"></div></div><canvas class="hero-canvas" id="lens-artwork" aria-hidden="true"></canvas></div><section class="hero" id="home"><div class="container hero-inner"><h1 class="hero-sentence"><span class="hero-copy-layer" data-hero-current><span class="hero-line"><span data-hero-prefix>Uma nova forma de</span></span> <span class="hero-line"><i data-hero-word>conectar seu futuro.</i></span></span></h1>${seal()}<p class="hero-caption">Sua vida acadêmica.<br>Um universo de possibilidades.</p></div><div class="intro-greeting" aria-hidden="true"><span>Olá.</span><span>Somos a Innecta.</span></div></section>${renderScienceSection()}</div><div class="container home-content"><section id="partners"><span id="works" class="legacy-anchor" aria-hidden="true"></span><h2 class="eyebrow reveal">CONEXÕES QUE FAZEM SUA TRAJETÓRIA AVANÇAR</h2><p class="capability-words reveal">${['Visão','Currículo Studio','Instituições','Comparar','Residência','Internacional','Meu Caminho','Pesquisa','Ligas','Mentor','Acervo','Club'].map(x=>`<span>${x}</span>`).join(' ')}</p><a class="text-link reveal" href="/modulos/trajetoria/">Explore as possibilidades ${arrow}</a></section><section id="manifesto"><h2 class="eyebrow reveal">${star} NOSSA VISÃO</h2><p class="manifesto-lines"><span>Não é sobre chegar</span><span>mais <i>rápido.</i></span><span>É sobre construir</span><span>um caminho que</span><span>faça <i>sentido.</i></span></p><span class="manifesto-star" aria-hidden="true">${star}</span></section><section id="strengths">${principles.map((p,i)=>`<section class="principle reveal" id="principle-${['conectar','construir','acompanhar'][i]}"><h3 class="eyebrow">${e(p.title)}</h3><div class="principle-content">${renderPrincipleVisual(i)}<div class="principle-text"><span class="principle-number">0${i+1}</span><p>${e(p.body || p.description || p.text)}</p></div></div></section>`).join('')}</section><div class="marquee" aria-hidden="true"><p data-marquee>Seu futuro é <i>feito de conexões.</i></p></div></div><div class="container"><section class="editorial-cta reveal"><h2 class="eyebrow">${star} CONHECIMENTO QUE CIRCULA</h2><div class="editorial-cta-content"><p>Nenhuma trajetória se constrói sozinha. Aproximamos perguntas, oportunidades e pessoas para transformar o que você aprende em caminhos que pode percorrer.</p><a class="circle-link" href="/comunidade/"><span>Conheça<br>a comunidade</span>${arrow}</a></div></section><section class="tiles tiles--rotated" id="product-mosaic" aria-label="Perspectivas do ecossistema Innecta"><div class="tiles__wrap">${[0,1,2,3].map((r)=>`<div class="tiles__line" data-tile-row="${r}">${[0,1,2].map((c)=>{const p=projects[(r*3+c)%projects.length];return `<div class="tiles__line-img"><img src="/assets/tiles/${e(p.slug)}.png" alt="" loading="lazy" decoding="async" width="2880" height="1800"></div>`}).join('')}</div>`).join('')}</div></section>${renderBookSection({star,arrow})}</div>`;}
export function renderContent(page,slug){if(page==='project')return renderProject(projects.find(p=>p.slug===slug),projects);if(page==='community')return renderCommunity(editorial,projects);if(page==='directory')return renderDirectory(directoryProfiles);if(page==='404')return `<section class="hero not-found-hero" data-render-mode="pending"><div class="hero-fallback" aria-hidden="true"><div class="fallback-field"></div><div class="fallback-lens"></div></div><canvas class="hero-canvas" aria-hidden="true"></canvas><div class="container not-found"><p class="eyebrow">404 · UM DESVIO NO CAMINHO</p><h1>Vamos encontrar<br>um novo <i>começo.</i></h1><a class="text-link" href="/">Voltar para a Innecta ${arrow}</a></div></section>`;return renderHome();}
export function renderDocument({page='home',slug='',build='dev'}){const p=projects.find(p=>p.slug===slug);if(page==='project'&&!p)return renderDocument({page:'404',build});const title=page==='project'?`${p.title} — Innecta`:page==='community'?'Comunidade — Innecta':page==='directory'?'Percursos — Innecta':page==='404'?'Página não encontrada — Innecta':'Innecta — Sua trajetória, um novo olhar';return `<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#160e12"><title>${e(title)}</title><meta name="description" content="${e(p?.summary || 'Um ecossistema para conectar sua trajetória acadêmica e médica. Explore planejamento, pesquisa, oportunidades, comunidade e orientação com a Innecta.')}"><meta name="innecta-build" content="${e(build)}"><meta property="og:type" content="website"><meta property="og:title" content="${e(title)}"><meta property="og:description" content="Uma nova perspectiva para sua trajetória acadêmica e médica. Innecta, em pré-lançamento."><meta name="twitter:card" content="summary_large_image"><link rel="icon" type="image/svg+xml" href="/assets/favicon.svg"><link rel="preload" as="font" href="/assets/Roobert-Regular.woff2" type="font/woff2" crossorigin>${['home','directory','404'].includes(page)?'<link rel="modulepreload" href="/js/vendor/three-scene.js">':''}<link rel="stylesheet" href="/css/main.css"><link rel="stylesheet" href="/css/pages.css"><link rel="stylesheet" href="/css/video.css">${page==='home'?'<link rel="stylesheet" href="/css/science-globe.css"><link rel="stylesheet" href="/css/principle-visuals.css"><link rel="stylesheet" href="/css/tiles.css"><link rel="stylesheet" href="/css/book.css"><link rel="stylesheet" href="/css/book-fallback.css">':''}<noscript><style>.hero .hero-fallback{opacity:1;visibility:visible}</style>${page==='home'?'<style>.shared-artwork .hero-fallback{opacity:1;visibility:visible}.home-world .shared-artwork{height:100%}</style>':''}</noscript></head><body data-page="${page}" data-build="${build}">${page==='project'?'':header(page)}<main id="main" data-scroll-container tabindex="-1">${renderContent(page,slug)}${['home','community'].includes(page)?footer():''}</main><dialog class="profile-dialog" aria-label="Percurso Innecta"><div class="modal-content"></div></dialog><div class="dot-cursor" aria-hidden="true"><span></span></div><script type="module" src="/js/app.js"></script></body></html>`;}
